      <input id="todo-input" type="text" placeholder="What needs to be done?" autocomplete="off" maxlength="500">
      <button id="add-btn">Add</button>
    </div>
    <ul id="todo-list"></ul>
    <div class="empty" id="empty-state" hidden>No todos here.</div>
    <div class="footer">
      <span class="count" id="count"></span>
      <div class="filters" id="filters">
        <button data-filter="all" class="active">All</button>
        <button data-filter="active">Active</button>
        <button data-filter="completed">Completed</button>
      </div>
    </div>
  </div>
</div>

<script>
(function () {
  'use strict';

  var STORAGE_KEY = 'todo_ollama-mimo-v2.6-flash-rl-mxfp4_01';
  var todos = [];
  var filter = 'all';

  var input = document.getElementById('todo-input');
  var addBtn = document.getElementById('add-btn');
  var list = document.getElementById('todo-list');
  var emptyState = document.getElementById('empty-state');
  var countEl = document.getElementById('count');
  var filtersEl = document.getElementById('filters');

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return;
      var parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        todos = parsed.filter(function (t) {
          return t && typeof t.text === 'string' && typeof t.completed === 'boolean';
        }).map(function (t) {
          return { id: t.id || String(Date.now()) + Math.random().toString(36).slice(2), text: t.text, completed: t.completed };
        });
      }
    } catch (e) { todos = []; }
  }

  function save() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(todos)); } catch (e) {}
  }

  function addTodo() {
    var text = input.value.trim();
    if (!text) return;
    todos.push({ id: String(Date.now()) + Math.random().toString(36).slice(2), text: text, completed: false });
    input.value = '';
    save();
    render();
    input.focus();
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) { todos[i].completed = !todos[i].completed; break; }
    }
    save();
    render();
  }

  function deleteTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
    render();
  }

  function visibleTodos() {
    if (filter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (filter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function render() {
    var visible = visibleTodos();
    list.innerHTML = '';

    visible.forEach(function (todo) {
      var li = document.createElement('li');
      li.className = 'todo' + (todo.completed ? ' completed' : '');

      var checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = todo.completed;
      checkbox.addEventListener('change', function () { toggleTodo(todo.id); });

      var span = document.createElement('span');
      span.className = 'text';
      span.textContent = todo.text;
      span.addEventListener('click', function () { toggleTodo(todo.id); });

      var del = document.createElement('button');
      del.className = 'delete';
      del.textContent = '✕';
      del.setAttribute('aria-label', 'Delete todo');
      del.title = 'Delete';
      del.addEventListener('click', function () { deleteTodo(todo.id); });

      li.appendChild(checkbox);
      li.appendChild(span);
      li.appendChild(del);
      list.appendChild(li);
    });

    emptyState.hidden = visible.length !== 0;

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var remainingLabel = activeCount === 1 ? '1 item left' : activeCount + ' items left';
    countEl.textContent = remainingLabel;

    var buttons = filtersEl.querySelectorAll('button');
    for (var i = 0; i < buttons.length; i++) {
      buttons[i].classList.toggle('active', buttons[i].getAttribute('data-filter') === filter);
